AWS Application Load Balancer (ALB).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AWS Application Load Balancer (ALB) container

Container_Boundary(aws_alb_container, "AWS Application Load Balancer (ALB)") {
    Component(AWS_Application_Load_Balancer_ALB, "AWS Application Load Balancer (ALB)", "AWS ALB", "Ingress routing with TLS 1.3 and WAF to eliminate API Gateway latency overhead.")
}

Component(Scoring_Engine, "Scoring Engine", "Java (Spring Boot / gRPC)", "High-performance hot-path scoring engine meeting <50ms P99 latency.")
Component(Case_Management_Service, "Case Management Service", "Node.js / React", "Case management UI ensuring analysts never access raw card data.")

Rel(AWS_Application_Load_Balancer_ALB, Scoring_Engine, "gRPC/HTTPS over TLS", "gRPC/HTTPS")
Rel(AWS_Application_Load_Balancer_ALB, Case_Management_Service, "HTTPS", "HTTPS")

@enduml

